def arrange_coins(n):
    lo, hi = 0, n
    ans = 0

    while lo <= hi:
        mid = (lo + hi) // 2
        coins_needed = mid * (mid + 1) // 2
        if coins_needed <= n:
            ans = mid
            lo = mid + 1
        else:
            hi = mid - 1

    return ans

